 28	public class PgPersistencia implements Persistencia {
 29	
 30	    private static final Logger log = LoggerFactory.getLogger(PgPersistencia.class);
 31	
 32	    private static final String ESQUEMA = """
 33	            CREATE TABLE IF NOT EXISTS produto (
 34	                sku TEXT PRIMARY KEY,
 35	                nome TEXT NOT NULL,
 36	                preco NUMERIC(14,2) NOT NULL,
 37	                peso_kg NUMERIC(10,2) NOT NULL,
 38	                estoque INTEGER NOT NULL CHECK (estoque >= 0),
 39	                fora_de_linha BOOLEAN NOT NULL);
 40	            CREATE TABLE IF NOT EXISTS cliente (
 41	                cpf TEXT PRIMARY KEY,
 42	                email TEXT NOT NULL,
 43	                saldo_credito NUMERIC(14,2) NOT NULL);
 44	            CREATE TABLE IF NOT EXISTS pedido (
 45	                id TEXT PRIMARY KEY,
 46	                cpf TEXT NOT NULL,
 47	                situacao TEXT NOT NULL,
 48	                criado_em TEXT NOT NULL,
 49	                codigo_rastreio TEXT,
 50	                id_transacao TEXT,
 51	                resumo TEXT NOT NULL,
 52	                itens TEXT NOT NULL);
 53	            CREATE TABLE IF NOT EXISTS aviso (
 54	                id TEXT PRIMARY KEY,
 55	                seq BIGINT NOT NULL,
 56	                cpf TEXT NOT NULL,
 57	                tipo TEXT NOT NULL,
 58	                pedido_id TEXT NOT NULL,
 59	                situacao TEXT NOT NULL)""";
 60	
 61	    private final PgConexao conexao;
 62	    private final JsonMapper json = JsonMapper.builder().build();
 63	
 64	    public PgPersistencia(PgConexao conexao) {
 65	        this.conexao = conexao;
 66	    }
 67	
 68	    @Override
 69	    public Estado carregar() {
 70	        prepararBanco();
 71	        Estado estado = new Estado();
 72	        for (String[] l : conexao.consultar(
 73	                "SELECT sku, nome, preco, peso_kg, estoque, fora_de_linha FROM produto ORDER BY sku")) {
 74	            estado.produtos.put(l[0], new Produto(l[0], l[1], Dinheiro.arredondar(new BigDecimal(l[2])),
 75	                    Dinheiro.arredondar(new BigDecimal(l[3])), Integer.parseInt(l[4]), l[5].equals("t")));
 76	        }
 77	        for (String[] l : conexao.consultar("SELECT cpf, email, saldo_credito FROM cliente")) {
 78	            estado.clientes.put(l[0], new Cliente(l[0], l[1], Dinheiro.arredondar(new BigDecimal(l[2]))));
 79	        }
 80	        for (String[] l : conexao.consultar("SELECT id, cpf, situacao, criado_em, codigo_rastreio, id_transacao, "
 81	                + "resumo, itens FROM pedido ORDER BY criado_em, id")) {
 82	            estado.adicionarPedido(new Pedido(l[0], l[1], SituacaoPedido.valueOf(l[2]), Instant.parse(l[3]),
 83	                    json.readValue(l[6], Resumo.class), json.readValue(l[7], new TypeReference<List<Item>>() { }),
 84	                    l[4], l[5]));
 85	        }
 86	        for (String[] l : conexao.consultar("SELECT id, seq, cpf, tipo, pedido_id, situacao FROM aviso ORDER BY seq")) {
 87	            estado.adicionarAviso(new Aviso(l[0], Long.parseLong(l[1]), l[2], TipoAviso.valueOf(l[3]), l[4],
 88	                    l[5].equals("LIDO")));
 89	        }
 90	        return estado;
 91	    }
 92	
 93	    private void prepararBanco() {
 94	        conexao.consultar(ESQUEMA);
 95	        List<String> comandos = new ArrayList<>();
 96	        if (conexao.consultar("SELECT 1 FROM produto LIMIT 1").isEmpty()) {
 97	            log.info("Banco vazio: carregando o catálogo inicial");
 98	            for (Produto p : Catalogo.inicial()) {
 99	                comandos.add("INSERT INTO produto (sku, nome, preco, peso_kg, estoque, fora_de_linha) VALUES ("
100	                        + texto(p.sku()) + "," + texto(p.nome()) + "," + p.preco().toPlainString() + ","
101	                        + p.pesoKg().toPlainString() + "," + p.estoque() + "," + p.foraDeLinha()
102	                        + ") ON CONFLICT (sku) DO NOTHING");
103	            }
104	        }
105	        conexao.transacao(comandos);
106	    }
107	
108	    @Override
109	    public void gravar(Mudancas m) {
110	        List<String> comandos = new ArrayList<>();
111	        for (Produto p : m.produtos) {
112	            comandos.add("INSERT INTO produto (sku, nome, preco, peso_kg, estoque, fora_de_linha) VALUES ("
113	                    + texto(p.sku()) + "," + texto(p.nome()) + "," + p.preco().toPlainString() + ","
114	                    + p.pesoKg().toPlainString() + "," + p.estoque() + "," + p.foraDeLinha()
115	                    + ") ON CONFLICT (sku) DO UPDATE SET nome = EXCLUDED.nome, preco = EXCLUDED.preco, "
116	                    + "peso_kg = EXCLUDED.peso_kg, estoque = EXCLUDED.estoque, "
117	                    + "fora_de_linha = EXCLUDED.fora_de_linha");
118	        }
119	        for (Cliente c : m.clientes) {
120	            comandos.add("INSERT INTO cliente (cpf, email, saldo_credito) VALUES (" + texto(c.cpf()) + ","
121	                    + texto(c.email()) + "," + c.saldoCredito().toPlainString()
122	                    + ") ON CONFLICT (cpf) DO UPDATE SET email = EXCLUDED.email, "
123	                    + "saldo_credito = EXCLUDED.saldo_credito");
124	        }
125	        for (Pedido p : m.pedidos) {
126	            comandos.add("INSERT INTO pedido (id, cpf, situacao, criado_em, codigo_rastreio, id_transacao, "
127	                    + "resumo, itens) VALUES (" + texto(p.id()) + "," + texto(p.cpf()) + ","
128	                    + texto(p.situacao().name()) + "," + texto(p.criadoEm().toString()) + ","
129	                    + textoOuNulo(p.codigoRastreio()) + "," + textoOuNulo(p.idTransacao()) + ","
130	                    + texto(json.writeValueAsString(p.resumo())) + "," + texto(json.writeValueAsString(p.itens()))
131	                    + ") ON CONFLICT (id) DO UPDATE SET situacao = EXCLUDED.situacao, "
132	                    + "codigo_rastreio = EXCLUDED.codigo_rastreio, id_transacao = EXCLUDED.id_transacao");
133	        }
134	        for (Aviso a : m.avisos) {
135	            comandos.add("INSERT INTO aviso (id, seq, cpf, tipo, pedido_id, situacao) VALUES (" + texto(a.id())
136	                    + "," + a.seq() + "," + texto(a.cpf()) + "," + texto(a.tipo().name()) + ","
137	                    + texto(a.pedidoId()) + "," + texto(a.lido() ? "LIDO" : "NOVO")
138	                    + ") ON CONFLICT (id) DO UPDATE SET situacao = EXCLUDED.situacao");
139	        }
140	        conexao.transacao(comandos);
141	    }
142	
143	    private static String textoOuNulo(String valor) {
144	        return valor == null ? "NULL" : texto(valor);
145	    }
146	
147	
148	    static String texto(String valor) {
149	        if (valor.indexOf('\0') >= 0) {
150	            throw new IllegalArgumentException("texto com caractere nulo");
151	        }
152	        return "'" + valor.replace("'", "''") + "'";
153	    }
154	}

